# Code generated by Claude
"""Low-friction floor contact points of the base, added to the model at load time.

The Tracer's wheel and caster meshes cannot roll (the base is velocity-driven), and their friction of 1.0 to 1.5 against the forced
velocity pitched the robot onto one front caster (a lean of up to 8 degrees, a 38 mm rise). This module puts the base on six small spheres
with a low friction instead (robot_specs.BASE_CONTACT_SPECS has the numbers and the reasoning) and switches the six wheel and caster
meshes off for collisions. Same pattern as src/pedestal.py: the XML stays untouched and RobotSimulator applies this before compiling.
"""

import mujoco


def add_base_contacts(spec, contact_specs):
    """Adds the six contact spheres to the base body and stops the wheel and caster meshes from colliding.

    The spheres are massless (density 0), sit on the base body, have contype = the specs' bit and conaffinity 0, and carry the specs' friction
    with a geom priority above the floor's so that their friction is the one used. The floor's conaffinity gains the bit, so the spheres touch
    only the floor. The wheel and caster mesh geoms get contype and conaffinity 0.

    Args:
        spec (mujoco.MjSpec): The model specification, before compiling.
        contact_specs (dict): robot_specs.BASE_CONTACT_SPECS.

    Raises:
        ValueError: If the base body, the floor geom or one of the mesh geoms is not in the model.
    """
    body = spec.body(contact_specs["body"])
    floor = spec.geom(contact_specs["floor_geom"])
    if body is None or floor is None:
        raise ValueError(f"base contacts: body '{contact_specs['body']}' or floor geom '{contact_specs['floor_geom']}' not found in model")
    bit = contact_specs["bit"]
    floor.conaffinity |= bit
    for name in contact_specs["mesh_geoms"]:
        geom = spec.geom(name)
        if geom is None:
            raise ValueError(f"base contacts: mesh geom '{name}' not found in model")
        geom.contype = 0
        geom.conaffinity = 0
    for name, pos in contact_specs["points"].items():
        g = body.add_geom()
        g.name = f"contact_{name}"
        g.type = mujoco.mjtGeom.mjGEOM_SPHERE
        g.size[0] = contact_specs["radius"]
        g.pos = list(pos)
        g.density = 0.0
        g.contype = bit
        g.conaffinity = 0
        g.condim = 3
        g.friction = list(contact_specs["friction"])
        g.priority = 1
        g.rgba = [0.9, 0.2, 0.2, 0.0]            # invisible
        g.group = 4
